1	import "server-only";
2	import { db } from "@/lib/db";
3	import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
4	import { geoLocateIp } from "@/lib/geo-ip";
5	import { GAME_DISPLAY, GAME_ART_SLUG, type GameFamily } from "@/lib/games";
6	import { FREEMC_GAME_TYPES, FREEMC_GAME_MODES } from "@/lib/free-minecraft-control";
7	import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
8	import { connectAddress } from "@/lib/nx/connect-address";
9	import { gamePlanSpecs, specLine } from "@/lib/nx/plan-specs";
10	import { renewalCharge } from "@/lib/renewal-charge";
11	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
12	import { extraDiskPerGbCents } from "@/lib/disk-expand";
13	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
14	import { annualDiscountPct } from "@/lib/annual-discount";
15	import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
16	import { taxContextForUser } from "@/lib/tax";
17	// THE renewal-price formula for shared hosting — worker/product-renewals.ts's
18	// sweep charges through this same function, so the number shown here is the
19	// number that will actually be charged. See hostingRenewalPrice's own comment.
20	import {
21	  hostingRenewalPrice,
22	  emailMonthlyBaseCents,
23	  frozenProductAnnualPct,
24	  productTermRenewalCents,
25	  subscriptionTermMonths,
26	} from "@/lib/product-billing";
27	
28	/**
29	 * One customer's whole estate, normalised into a single list.
30	 *
31	 * The six products live in genuinely different tables — a VPS and a game
32	 * server are both `Server` rows told apart by `gamePlanId`, shared hosting is
33	 * a `HostingAccount`, the free Minecraft tier is its own
34	 * `FreeMinecraftServer`, and domains/business email are `Domain` /
35	 * `EmailSubscription` rows — so this is the one place that flattens them into
36	 * a shape a single list can render. Everything below is read from the record;
37	 * nothing is inferred where the data doesn't exist (hosting has no region
38	 * column, so its location is geo-resolved from the node's real public IP the
39	 * same way the primary node's location was confirmed, and is left blank when
40	 * that lookup can't answer; a domain/email row has no server behind it at
41	 * all, so its location is left blank rather than guessed).
42	 */
43	export type ServiceKind = "vps" | "game" | "hosting" | "free" | "domain" | "email";
44	
45	/** The five buckets the page's stat row and status pills speak in. */
46	export type ServiceStatus = "running" | "pending" | "stopped" | "suspended" | "error" | "cancelled";
47	
48	export type ServiceRow = {
49	  id: string;
50	  kind: ServiceKind;
51	  /** What the customer named it (or the domain, for hosting/domain/email). */
52	  name: string;
53	  /** Where "Manage" goes. */
54	  href: string;
55	  typeLabel: string;
56	  /** The address a customer actually connects on. See `connectAddress`. */
57	  address: string | null;
58	  /** What that address IS, so the row can label it rather than guess. */
59	  addressLabel: "IP address" | "Connect" | "Website" | null;
60	  /** Second line under the name — plan/specs. */
61	  specs: string | null;
62	  status: ServiceStatus;
63	  statusLabel: string;
64	  location: { label: string; country: string } | null;
65	  renewalIso: string | null;
66	  /** Per-term price in cents; null when nothing is charged (free tier). */
67	  renewalCents: number | null;
68	  /** Billing term in months, so "/mo" vs "/yr" is honest. */
69	  termMonths: number;
70	  /** Game family id, for the box-art thumbnail. */
71	  gameFamily: string | null;
72	  /** Hosting/domain/email only — the domain name the row is sold against. */
73	  domain: string | null;
74	  createdAtIso: string;
75	
76	  /* ── card preview art ───────────────────────────────────────────────────
77	     Every card leads with a picture. Where it comes from depends on the
78	     product, and the rule is the same one the brief sets out: show the real
79	     thing if there is one, otherwise the stock plate for that product. */
80	
81	  /** The image the card leads with. Never null — there is always a fallback. */
82	  previewSrc: string;
83	  /** Which of the three sources `previewSrc` came from — the card badges it. */
84	  previewSource: "game-art" | "customer" | "stock";
85	  /**
86	   * Hosting only: the live site can be framed over the stock plate, so a plan
87	   * that is actually serving something shows THAT instead of the plate. There
88	   * is no screenshot service behind this — it is the customer's own site or
89	   * the plate, never a stand-in picture of some other website.
90	   */
91	  siteToFrame: string | null;
92	  /** VPS rows let the customer replace the stock plate with their own image. */
93	  canSetPreview: boolean;
94	  /**
95	   * VPS only: what it is actually running. Every VPS on the stock plate would
96	   * otherwise be the same picture, and the OS is the one thing that genuinely
97	   * tells them apart at a glance.
98	   */
99	  os: { family: string; name: string } | null;
100	};
101	
102	/** Tolerant status mapper: every product spells its states differently, and a
103	 *  new value should degrade to something sane rather than crash a list. */
104	function normalizeStatus(raw: string): { status: ServiceStatus; label: string } {
105	  const s = (raw ?? "").toUpperCase();
106	  if (["RUNNING", "ACTIVE", "ONLINE"].includes(s)) return { status: "running", label: "Running" };
107	  // The free tier's container states: READY means the container exists —
108	  // mc-router owns whether it is awake right now, and this list deliberately
109	  // doesn't claim to know that, so it says Ready rather than Running.
110	  if (s === "READY") return { status: "running", label: "Ready" };
111	  if (["PENDING", "PROVISIONING", "CREATING", "REINSTALLING", "STARTING"].includes(s)) {
112	    return { status: "pending", label: s === "REINSTALLING" ? "Reinstalling" : "Pending" };
113	  }
114	  if (["STOPPED", "SLEEPING", "OFFLINE"].includes(s)) {
115	    return { status: "stopped", label: s === "SLEEPING" ? "Asleep" : "Stopped" };
116	  }
117	  if (["SUSPENDED"].includes(s)) return { status: "suspended", label: "Suspended" };
118	  // Domain-only inbound-transfer states (DomainStatus) — without these two, the
119	  // fallback below stringifies "TRANSFER_PENDING" into "Transfer_pending".
120	  if (s === "TRANSFER_PENDING") return { status: "pending", label: "Transferring" };
121	  if (s === "TRANSFER_FAILED") return { status: "error", label: "Transfer failed" };
122	  if (["DELETING", "DELETED", "CANCELLED", "CANCELED", "TERMINATED", "EXPIRED"].includes(s)) {
123	    return { status: "cancelled", label: s === "DELETING" ? "Deleting" : "Cancelled" };
124	  }
125	  if (["ERROR", "FAILED"].includes(s)) return { status: "error", label: "Failed" };
126	  return { status: "pending", label: raw ? raw.charAt(0) + raw.slice(1).toLowerCase() : "Unknown" };
127	}
128	
129	function regionLocation(region: string | null | undefined) {
130	  if (!region) return null;
131	  const label = REGION_LABELS[region];
132	  if (!label) return null;
133	  return { label, country: REGION_COUNTRY[region] ?? "" };
134	}
135	
136	
137	
138	/** Stock plates, for a service with nothing of its own to show yet. */
139	const STOCK_PREVIEW = {
140	  vps: "/nx/preview/vps.webp",
141	  hosting: "/nx/preview/hosting.webp",
142	  // Neither product has its own wide 16:4 rack plate yet — domains reuse the
143	  // real hero art from /dashboard/domains rather than a stretched icon; email
144	  // has no dedicated wide art at all, so it falls back to its own service mark.
145	  domain: "/nx/hero-domains-globe.webp",
146	  email: "/nx/svc/email.webp",
147	} as const;
148	
149	/** Landscape key art for a game family, which every family in the catalogue has. */
150	function gameHeroArt(family: string | null): string | null {
151	  const slug = family ? GAME_ART_SLUG[family as GameFamily]?.hero : null;
152	  return slug ? `/games/art/${slug}_hero.jpg` : null;
153	}
154	
155	/**
156	 * Where a Server row's card image comes from, in priority order: the image the
157	 * customer set, then the game's own key art, then the stock rack plate. The
158	 * `v` stamp is the preview's updatedAt, so replacing an image busts the cache
159	 * without making the route itself uncacheable.
160	 */
161	function serverPreview(
162	  id: string, isGame: boolean, family: string | null, previewStamp: Date | null,
163	): Pick<ServiceRow, "previewSrc" | "previewSource" | "siteToFrame" | "canSetPreview"> {
164	  if (previewStamp) {
165	    return {
166	      previewSrc: `/api/services/preview/${id}?v=${previewStamp.getTime()}`,
167	      previewSource: "customer",
168	      siteToFrame: null,
169	      canSetPreview: true,
170	    };
171	  }
172	  const art = isGame ? gameHeroArt(family) : null;
173	  return {
174	    previewSrc: art ?? STOCK_PREVIEW.vps,
175	    previewSource: art ? "game-art" : "stock",
176	    siteToFrame: null,
177	    // Game servers lead with their own key art, which is better than anything a
178	    // customer would upload — the swap is offered on VPS rows only.
179	    canSetPreview: !isGame,
180	  };
181	}
182	
183	
184	export async function listServices(userId: string): Promise<ServiceRow[]> {
185	  const user = await db.user.findUnique({ where: { id: userId } });
186	  if (!user) return [];
187	
188	  // The play-subdomain base is an admin SETTING shared by free and paid game
189	  // servers, not a constant — reading it keeps the connect address honest if
190	  // the owner ever moves it off play.nxeon.cloud.
191	  const [servers, hosting, freeMc, domains, emailSubs, gameBase] = await Promise.all([
192	    db.server.findMany({
193	      // NxCloud instances are backed by a Server but sold as their own product,
194	      // so they stay out of this list exactly as they do on /dashboard/servers.
195	      where: { userId, nxcloudInstance: { is: null } },
196	      include: {
197	        plan: true,
198	        gamePlan: true,
199	        osTemplate: true,
200	        // `dedicatedIp` is not decoration here — renewalCharge bills it.
201	        dedicatedIp: { select: { address: true } },
202	        node: { select: { region: true, publicIp: true } },
203	        portForwards: { select: { publicPort: true, guestPort: true } },
204	        // Only the stamp — the bytes are served by their own route, and must
205	        // never be dragged into a list query.
206	        preview: { select: { updatedAt: true } },
207	      },
208	      orderBy: { createdAt: "desc" },
209	    }),
210	    db.hostingAccount.findMany({
211	      where: { userId },
212	      include: { plan: true, node: { select: { publicIp: true, name: true } } },
213	      orderBy: { createdAt: "desc" },
214	    }),
215	    db.freeMinecraftServer.findUnique({ where: { userId } }),
216	    // Only a domain that is actually registered and live is a "service" the
217	    // customer holds today — a failed registration, an expired name or a
218	    // transfer that never completed isn't something to renew or manage here.
219	    // Matches the "real, owned, currently active" filter app/dashboard/domains
220	    // uses for its own active-count tile.
221	    db.domain.findMany({
222	      where: { userId, status: "ACTIVE" },
223	      orderBy: { createdAt: "desc" },
224	    }),
225	    // Same "not cancelled" filter app/dashboard/email/page.tsx lists against —
226	    // a suspended (unpaid) mailbox is still a service to show and fix, only a
227	    // cancelled one is gone.
228	    db.emailSubscription.findMany({
229	      where: { userId, status: { not: "CANCELLED" } },
230	      include: { emailPlan: true },
231	      orderBy: { createdAt: "desc" },
232	    }),
233	    gameSubdomainBase(),
234	  ]);
235	
236	  // The account's OWN captured/uploaded picture of its primary site — the
237	  // same one SitePreview.tsx (hosting account management) shows and lets the
238	  // customer (re)capture. The card grid used to never look at this at all:
239	  // every hosting row always got the flat stock plate, ignoring a picture
240	  // the customer had already generated. One batched query, keyed by
241	  // accountId, so N hosting rows cost one extra query rather than N.
242	  const primaryThumbByAccount = hosting.length
243	    ? new Map(
244	        (
245	          await db.hostingSiteThumb.findMany({
246	            where: { accountId: { in: hosting.map((h) => h.id) }, siteKey: "primary", status: "READY", sizeBytes: { gt: 0 } },
247	            select: { id: true, accountId: true, updatedAt: true },
248	          })
249	        ).map((t) => [t.accountId, t])
250	      )
251	    : new Map<string, { id: string; updatedAt: Date }>();
252	
253	  /* What a server ACTUALLY renews at.
254	   *
255	   * `plan.priceCents` is not that number: it ignores the term (an annual server
256	   * renews at 12x less the frozen annual discount), it ignores every add-on the
257	   * customer really is billed for each cycle (dedicated IP, extra root disk,
258	   * paid backup retention), and for a game server it is the wrong plan
259	   * entirely — a game row carries BOTH a base planId and a gamePlanId and is
260	   * sold at the game plan's flat price. lib/renewal-quote.ts records what
261	   * happened the last two times someone wrote that second formula. So this
262	   * prices through `renewalCharge`, the same function worker/billing.ts, the
263	   * saved-card path and the Renew now button all CHARGE through. */
264	  const paid = servers.filter((s) => !s.isFree);
265	  const taxRatePercent = (await taxContextForUser(user)).ratePercent;
266	  // Hosting's renewal price needs `extraDiskPerGbCents`/`annualDiscountPct`, and
267	  // email's needs `annualDiscountPct` too (see `hostingRenewalPrice` below and
268	  // the email renewal calc further down) — so this can't stay gated on paid VPS
269	  // servers alone, or a customer with only hosting/email gets the same
270	  // DEFAULT_ANNUAL_DISCOUNT_PCT fallback a brand-new install would.
271	  const prices = paid.length > 0 || hosting.length > 0 || emailSubs.length > 0
272	    ? {
273	        ipMonthlyCents: await dedicatedIpMonthlyCents(),
274	        extraDiskPerGbCents: await extraDiskPerGbCents(),
275	        backupPlusCents: await backupPlusMonthlyCents(),
276	        annualDiscountPct: await annualDiscountPct(),
277	        taxRatePercent,
278	      }
279	    : {
280	        ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0,
281	        annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent,
282	      };
283	
284	  const rows: ServiceRow[] = [];
285	
286	  for (const s of servers) {
287	    const isGame = s.gamePlanId !== null;
288	    const st = normalizeStatus(s.status);
289	    const family = s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? null;
290	    const gameName = family ? GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family : null;
291	    const charge = renewalCharge(s, prices);
292	    rows.push({
293	      id: s.id,
294	      kind: isGame ? "game" : "vps",
295	      name: s.label || s.hostname,
296	      href: `/dashboard/servers/${s.id}`,
297	      typeLabel: isGame ? gameName ?? "Game Server" : "VPS Server",
298	      ...connectAddress(s, gameBase),
299	      specs: isGame
300	        ? gamePlanSpecs(s.gamePlan?.name, gameName, s.gamePlan?.slots)
301	        : s.plan
302	          ? specLine(s.plan.cpuCores, s.plan.ramMB, s.plan.diskGB, s.plan.storageTier)
303	          : null,
304	      status: st.status,
305	      statusLabel: st.label,
306	      location: regionLocation(s.node?.region),
307	      renewalIso: s.expiresAt ? s.expiresAt.toISOString() : null,
308	      renewalCents: s.isFree ? null : charge.totalCents,
309	      termMonths: s.isFree ? 1 : charge.months,
310	      gameFamily: isGame ? family : null,
311	      domain: null,
312	      createdAtIso: s.createdAt.toISOString(),
313	      ...serverPreview(s.id, isGame, family, s.preview?.updatedAt ?? null),
314	      os: !isGame && s.osTemplate
315	        ? {
316	            family: s.osTemplate.logo || s.osTemplate.family,
317	            // `name` is often already the full "Ubuntu 24.04 LTS", so appending
318	            // `version` unconditionally produced "Ubuntu 24.04 LTS 24.04".
319	            name: s.osTemplate.version && !s.osTemplate.name.includes(s.osTemplate.version)
320	              ? `${s.osTemplate.name} ${s.osTemplate.version}`
321	              : s.osTemplate.name,
322	          }
323	        : null,
324	    });
325	  }
326	
327	  for (const h of hosting) {
328	    const st = normalizeStatus(h.status);
329	    // No region column on HostingNode — resolve the node's real public IP
330	    // instead of inventing a city, and leave it blank if that can't answer.
331	    const geo = geoLocateIp(h.node?.publicIp ?? null);
332	    rows.push({
333	      id: h.id,
334	      kind: "hosting",
335	      name: h.primaryDomain,
336	      href: `/dashboard/hosting/${h.id}`,
337	      typeLabel: "Shared Hosting",
338	      // The name IS the domain here, so repeating it as an address would just
339	      // print the same string twice in the same card.
340	      address: null,
341	      addressLabel: "Website",
342	      specs: [h.plan?.name, `${Math.round(h.diskQuotaMB / 1024)} GB disk`].filter(Boolean).join(" • ") || null,
343	      status: st.status,
344	      statusLabel: st.label,
345	      location: geo?.city ? { label: geo.city, country: (geo.country ?? "").toLowerCase() } : null,
346	      renewalIso: h.expiresAt ? h.expiresAt.toISOString() : null,
347	      // `h.plan.priceCents` is the raw monthly list price — it ignores the
348	      // annual-term discount and any extra-disk add-on the account is really
349	      // billed for each cycle. `hostingRenewalPrice` is the SAME function
350	      // worker/product-renewals.ts charges through, so this is never a display
351	      // number that drifts from what actually gets charged.
352	      renewalCents: h.plan ? hostingRenewalPrice(h, prices.annualDiscountPct, prices.extraDiskPerGbCents) : null,
353	      termMonths: h.termMonths ?? 1,
354	      gameFamily: null,
355	      domain: h.primaryDomain,
356	      createdAtIso: h.createdAt.toISOString(),
357	      ...(() => {
358	        const thumb = primaryThumbByAccount.get(h.id);
359	        return thumb
360	          ? {
361	              previewSrc: `/api/hosting/thumb?id=${thumb.id}&v=${thumb.updatedAt.getTime()}`,
362	              previewSource: "customer" as const,
363	            }
364	          : { previewSrc: STOCK_PREVIEW.hosting, previewSource: "stock" as const };
365	      })(),
366	      // Only a plan that is actually live is worth framing — a suspended or
367	      // still-provisioning account would frame an error page. Skipped
368	      // entirely when a real captured/uploaded picture already exists: the
369	      // iframe is a LIVE view (can render blank/default-page content the
370	      // stock plate at least doesn't), the thumbnail is a snapshot the
371	      // customer chose to keep — once one exists, show THAT, not both
372	      // layered on top of each other.
373	      siteToFrame: st.status === "running" && !primaryThumbByAccount.has(h.id) ? h.primaryDomain : null,
374	      canSetPreview: false,
375	      os: null,
376	    });
377	  }
378	
379	  for (const d of domains) {
380	    const st = normalizeStatus(d.status);
381	    rows.push({
382	      id: d.id,
383	      kind: "domain",
384	      name: d.name,
385	      href: `/dashboard/domains/${d.id}`,
386	      typeLabel: "Domain",
387	      // The name IS the domain — same reasoning as the hosting row above.
388	      address: null,
389	      addressLabel: "Website",
390	      specs: d.nameservers.length === 0 ? "Nxeon DNS" : "Custom DNS",
391	      status: st.status,
392	      statusLabel: st.label,
393	      // DomainStatus has no region: a registration has no server behind it.
394	      location: null,
395	      renewalIso: d.expiresAt ? d.expiresAt.toISOString() : null,
