/**
 * Where the deploy wizard's region cards measure latency TO.
 *
 * The number on a region card ("Singapore · Asia · 38 ms") is a real round-trip
 * measured by the visitor's own browser (components/nx/useRegionLatency.ts) —
 * never a nominal or estimated figure (lib/nx/catalog.ts's `Region.ms` is
 * nominal and is deliberately NOT what the card shows). A browser can only
 * time a request to something it can actually reach over HTTPS, so each
 * region needs a small endpoint physically served FROM that region. This file
 * says which URL that is, per region code, and returns nothing for a region
 * that has none — the card then shows a neutral "— ms", not a guess.
 *
 * Sources, in order:
 *  1. `REGION_PROBE_URLS` (env), e.g.
 *       REGION_PROBE_URLS="sgp1=/api/tools/ping,fsn1=https://fsn1-probe.example/ping"
 *     Only same-origin paths ("/...") or absolute https:// URLs are accepted.
 *     Cross-origin probes are fetched `no-cors`, so any tiny static file with
 *     `Cache-Control: no-store` works — no CORS headers needed.
 *  2. Default when the env var is unset: the portal itself is served from the
 *     PRIMARY node (nginx → nxeon-web on the same box — see CLAUDE.md), so the
 *     app's own `/api/tools/ping` (the endpoint the public Latency Test tool
 *     already uses) is a genuine probe of the primary node's region. No other
 *     node serves anything a browser can reach over HTTPS today — node-2
 *     (fsn1) exposes only its Proxmox API / node-agent on self-signed certs and
 *     the NAT'd game/VM ports, none of which a browser can or should time.
 *
 * Server-only (reads process.env); the resolved map is handed to the client as
 * plain data on each `Region`.
 */

export function parseRegionProbeUrls(raw: string | undefined | null): Record<string, string> | null {
  if (!raw || !raw.trim()) return null;
  const out: Record<string, string> = {};
  for (const pair of raw.split(",")) {
    const eq = pair.indexOf("=");
    if (eq <= 0) continue;
    const code = pair.slice(0, eq).trim();
    const url = pair.slice(eq + 1).trim();
    if (!/^[a-z0-9-]{2,16}$/i.test(code)) continue;
    // Same-origin path or absolute https only — never http (mixed content on
    // the https portal), never javascript:/data: or anything else.
    if (!(url.startsWith("/") && !url.startsWith("//")) && !/^https:\/\/[^\s"'<>]+$/i.test(url)) continue;
    out[code] = url;
  }
  return out;
}

export function regionProbeUrls(
  nodes: { region: string; isPrimary: boolean }[],
  env: string | undefined = process.env.REGION_PROBE_URLS,
): Record<string, string> {
  const explicit = parseRegionProbeUrls(env);
  if (explicit) return explicit;
  const primary = nodes.find((n) => n.isPrimary);
  return primary ? { [primary.region]: "/api/tools/ping" } : {};
}

