const { chromium } = require('playwright');

(async () => {
  const base = process.argv[2]; // e.g. http://127.0.0.1:8080
  const path = process.argv[3]; // e.g. /dashboard/nxlabs/games/minecraft
  const out = process.argv[4];
  const email = `herofix-test-${Date.now()}@nxeon-internal.test`;

  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('console', (m) => console.log('CONSOLE', m.type(), m.text()));
  page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
  page.on('response', (r) => { if (!r.ok() && !r.url().includes('favicon')) console.log('BADRESP', r.status(), r.url()); });

  await page.goto(`${base}/register`, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(1500);
  await page.fill('#register-name', 'Hero Fix Test');
  await page.fill('#register-email', email);
  await page.fill('#register-password', 'HeroFixTest123!');
  await page.click('button:has-text("Create account")', { force: true });
  await page.waitForTimeout(3000);
  console.log('URL after submit:', page.url());
  await page.screenshot({ path: out.replace('.png', '-postsubmit.png') });

  await page.goto(`${base}${path}`, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(1500);
  console.log('Final URL:', page.url());
  await page.screenshot({ path: out, fullPage: false });
  await browser.close();
  console.log('done', email);
})().catch((e) => { console.error(e); process.exit(1); });

