 * see test/dayz-config.test.ts.
 */
export function updateDayZConfig(
  content: string,
  updates: Record<string, string>,
  missionTemplate?: string
): string {
  const lines = content.split(/\r?\n/);
  const seen = new Set<string>();
  const format = (key: string, raw: string) =>
    DAYZ_STRING_KEYS.has(key) ? `"${raw.replace(/"/g, '\\"')}"` : raw;
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    for (const key of Object.keys(updates)) {
      if (seen.has(key)) continue;
      if (new RegExp(`^${key}\\b\\s*=`).test(trimmed)) {
        lines[i] = `${key} = ${format(key, updates[key])};`;
        seen.add(key);
        break;
      }
    }
  }
  for (const key of Object.keys(updates)) {
    if (!seen.has(key)) lines.push(`${key} = ${format(key, updates[key])};`);
  }
  let next = lines.join("\n");

  if (missionTemplate !== undefined) {
    const escaped = missionTemplate.replace(/"/g, '\\"');
    const blockRe = /(class\s+Missions\s*\{[\s\S]*?class\s+DayZ\s*\{[\s\S]*?template\s*=\s*)"[^"]*"(\s*;)/;
    if (blockRe.test(next)) {
      next = next.replace(blockRe, `$1"${escaped}"$2`);
    } else {
      // No Missions block at all (a stripped-down or unexpected file) —
      // append a fresh one in the exact shape DayZ's own dedicated server
      // ships it in, rather than silently dropping the map choice.
      next += `\n\nclass Missions\n{\n    class DayZ\n    {\n        template="${escaped}";\n    };\n};\n`;
    }
  }
  return next;
}

/**
 * UNVERIFIED against a live box — no Steam account exists in this environment
 * to actually run SteamCMD or boot an `ich777/steamcmd:dayz` container (see
 * lib/dayz-steam.ts for the real, separate blocker this depends on). Not
 * added to `REAL_APPLY_FAMILIES` for that reason — same honest "built, not
 * yet graduated" state CS2/Eco/Empyrion/SpaceEngineers are already in for
 * their own file-based real-apply paths elsewhere in this file, rather than
 * claiming a confidence level this never actually reached. The one real gap:
 * ich777's own README documents a genuine footgun here — "changes to the
 * serverDZ.cfg in the main directory take no effect, you have to edit the
 * file .../saves/serverDZ.cfg" — so a naive single-path guess would silently
 * write to a file the server never reads. `remoteLocate`'s candidate list
 * below is ordered to prefer the documented `.../saves/` location first,
 * exactly the way `applyMinecraft`'s own equivalent uncertainty was resolved
 * before IT graduated into `REAL_APPLY_FAMILIES` — but that one was
 * confirmed against a real running server first; this one has not been.
 *
 * Once a real Nxeon-owned Steam account exists (lib/dayz-steam.ts's own "one
 * remaining manual step"), the actual graduation path is: provision one real
 * DayZ server, apply a distinctive `hostname`/`maxPlayers` change, read
 * `/opt/dayz/serverfiles/.../saves/serverDZ.cfg` back off disk directly (or
 * call `applyRealConfig` — exported for exactly this), confirm the value
 * really changed AND the server actually restarted with it, THEN add "dayz"
 * to REAL_APPLY_FAMILIES in lib/game-config.ts.
 */
async function applyDayZ(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  const path = await remoteLocate(
    conn,
    [
      "/opt/dayz/serverfiles/dayz/saves/serverDZ.cfg",
      "/opt/dayz/serverfiles/saves/serverDZ.cfg",
      "/opt/dayz/serverfiles/serverDZ.cfg",
    ],
    ["/opt/dayz"],
    "serverDZ.cfg"
  );
  if (!path) {
    return {
      ok: false,
      applied: [],
      notes: ["Could not locate serverDZ.cfg — nothing was changed (a restart is needed once the config path is confirmed against a live server)."],
    };
  }

  const existing = await sftpRead(sftp, path);
  if (existing == null) {
    return { ok: false, applied: [], notes: [`serverDZ.cfg disappeared at ${path} — nothing was changed.`] };
  }

  const flatUpdates: Record<string, string> = {};
  for (const key of ["hostname", "password", "passwordAdmin", "maxPlayers"]) {
    if (v[key] === undefined || v[key] === null) continue;
    flatUpdates[key] = String(v[key]);
  }
  const missionTemplate = v["missionTemplate"] != null ? String(v["missionTemplate"]) : undefined;

  const next = updateDayZConfig(existing, flatUpdates, missionTemplate);
  await sftpWrite(sftp, path, next);

