/**
 * Provision a real test game server on whichever DB this is run against
 * (relies on tsx's built-in .env autoload — run with cwd = the target
 * environment's directory, e.g. /opt/nxeon-staging). Mirrors scripts/e2e-test.ts's
 * pattern (same DB writes a real order performs) but for a GAME order instead
 * of a plain VPS: creates/reuses a test customer, funds the wallet, creates a
 * Server row with gamePlanId+osTemplateId set, enqueues PROVISION, and prints
 * status until RUNNING or timeout.
 *
 * Usage: npx tsx provision-test-game.ts <family> <osTemplateSlug> <gamePlanId> <planId>
 */
import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";

const db = new PrismaClient();

async function main() {
  const [family, osSlug, gamePlanId, planId] = process.argv.slice(2);
  if (!family || !osSlug || !gamePlanId || !planId) {
    throw new Error("usage: provision-test-game.ts <family> <osTemplateSlug> <gamePlanId> <planId>");
  }
  const email = `nxeon-capability-test-${family}@nxeon-internal.test`;
  let user = await db.user.findUnique({ where: { email } });
  if (!user) {
    user = await db.user.create({
      data: {
        email,
        name: `Nxeon Capability Test (${family})`,
        passwordHash: await bcrypt.hash("nxeon-capability-test-pw", 12),
        balanceCents: 500000,
      },
    });
  }

  const os = await db.osTemplate.findUnique({ where: { slug: osSlug } });
  const gamePlan = await db.gamePlan.findUnique({ where: { id: gamePlanId } });
  const plan = await db.plan.findUnique({ where: { id: planId } });
  if (!os || !gamePlan || !plan) throw new Error("missing os/gamePlan/plan row");

  const hostname = `nxtest-${family}-${Math.random().toString(36).slice(2, 8)}`;
  const server = await db.$transaction(async (tx) => {
    const s = await tx.server.create({
      data: {
        name: hostname,
        hostname,
        userId: user!.id,
        planId: plan.id,
        osTemplateId: os.id,
        gamePlanId: gamePlan.id,
        expiresAt: new Date(Date.now() + 30 * 86400_000),
      },
    });
    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
    return s;
  });

  console.log(`ordered ${family} test server ${server.id} (${hostname}), waiting for worker...`);
  const deadline = Date.now() + 60 * 60_000; // up to 60 minutes — game installs are large
  for (;;) {
    const s = await db.server.findUnique({ where: { id: server.id } });
    if (!s) throw new Error("server vanished");
    process.stdout.write(`  status=${s.status} vmid=${s.vmid ?? "-"} step=${s.provisioningStep ?? "-"}\n`);
    if (s.status === "RUNNING") {
      console.log(`DONE: ${family} server RUNNING. id=${s.id} vmid=${s.vmid} node?`);
      const withNode = await db.server.findUnique({ where: { id: s.id }, include: { node: true } });
      console.log(JSON.stringify({ id: s.id, hostname: s.hostname, nodeName: withNode?.node?.name, publicIp: withNode?.node?.publicIp }, null, 2));
      break;
    }
    if (s.status === "ERROR") {
      console.log(`FAILED: ${s.provisionError ?? "unknown error"}`);
      break;
    }
    if (Date.now() > deadline) {
      console.log("TIMEOUT waiting for provision");
      break;
    }
    await new Promise((r) => setTimeout(r, 15000));
  }
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

