import { GAME_FAMILIES, GAME_DISPLAY } from "@/lib/games";
import { GAME_CONTROL, GAME_LOG_TRACKING } from "@/lib/game-control";
import { REAL_APPLY_FAMILIES } from "@/lib/game-config";
import { INSTALLABLE_FAMILIES, RESOLVABLE_SOURCES } from "@/lib/mod-install-support";

for (const fam of GAME_FAMILIES) {
  const c = GAME_CONTROL[fam];
  const rcon = c?.rcon ?? "MISSING";
  const playerMgmt = rcon === "source" && !!c?.listCommand;
  const configPush = REAL_APPLY_FAMILIES.has(fam);
  const logTrack = !!(GAME_LOG_TRACKING as any)[fam];
  const modInstall = INSTALLABLE_FAMILIES.has(fam);
  const label = GAME_DISPLAY[fam as keyof typeof GAME_DISPLAY]?.name ?? fam;
  console.log([fam, label, configPush, playerMgmt, rcon, logTrack, modInstall].join("\t"));
}
EOF
